# v1.0 → v1.1 patch: 경영진 보고 v7 반영, 창원대 수주형, 영풍 10억·세부3 50억, 서연이화 삭제
import re, sys, pathlib
B = pathlib.Path(__file__).parent

def load(n): return (B / n).read_text(encoding='utf8')
def save(n, s): (B / n).write_text(s, encoding='utf8')

def sub(s, old, new, n=1):
    c = s.count(old)
    assert c == n, f'sub: expected {n} found {c}: {old[:60]}'
    return s.replace(old, new)

def repl_line(s, key, new_line):
    lines = s.split('\n')
    idx = [i for i, l in enumerate(lines) if key in l]
    assert len(idx) == 1, f'repl_line: {len(idx)} matches for {key[:60]}'
    lines[idx[0]] = new_line
    return '\n'.join(lines)

def del_line(s, key):
    lines = s.split('\n')
    idx = [i for i, l in enumerate(lines) if key in l]
    assert len(idx) == 1, f'del_line: {len(idx)} matches for {key[:60]}'
    del lines[idx[0]]
    return '\n'.join(lines)

